// دالة تخطي تسجيل الدخول والفتح المباشر على لوحة التحكم للتجريب
function finishLoading(){if(isAppLoaded)return;isAppLoaded=true;try{const splash=document.getElementById('splash-screen'),loginScreen=document.getElementById('login-screen'),header=document.getElementById('app-header');if(splash)splash.style.display='none';if(loginScreen)loginScreen.style.display='none';if(header)header.style.display='flex';openSection('main-dashboard');}catch(e){console.error(e);}}

// دالة إرسال الطلبات الآمنة إلى جوجل بدون تجميد الصفحة
function safePost(p,b,m,sM,cb){if(b){b.disabled=true;b.dataset.oH=b.innerHTML;b.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> جاري الحفظ...';}fetch(API_URL,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(p)}).then(()=>{if(m){m.innerText=sM||'تم بنجاح!';m.style.color='green';m.style.display='block';setTimeout(()=>m.style.display='none',3000);}if(cb)cb();}).catch(err=>{console.error(err);if(m){m.innerText='حدث خطأ في الاتصال!';m.style.color='red';m.style.display='block';}}).finally(()=>{if(b){b.disabled=false;if(b.dataset.oH)b.innerHTML=b.dataset.oH;}});}

// دالة إظهار وإخفاء كلمة المرور
function toggleLoginPassword(){const p=document.getElementById('loginPass'),i=document.getElementById('passToggleIcon');if(!p||!i)return;p.type=p.type==='password'?'text':'password';i.classList.toggle('fa-eye');i.classList.toggle('fa-eye-slash');}

// دالة تسجيل الدخول المباشر
function login(){finishLoading();}

// دالة التنقل بين أقسام لوحة التحكم الرئيسية
function openSection(sId){document.querySelectorAll('.content-area').forEach(el=>el.style.display='none');const t=document.getElementById(sId);if(t){t.style.display='block';window.scrollTo({top:0,behavior:'smooth'});}}

// دالة فتح أقسام الأدمن بدون طلب كلمة مرور أثناء التجريب
function openAdminSection(sId){openSection(sId);}

// دالة فتح المستندات العامة
function openGenericDoc(title){const t=document.getElementById('generic-doc-title');if(t)t.innerText=title;openSection('generic-doc-section');}

// دالة تحميل البيانات مع الحفظ والاسترجاع التلقائي من الكاش لمنع فراغ السجل نهائياً
function loadAppDataInit(){try{const cInc=localStorage.getItem('rmf_incidents');if(cInc)globalIncidents=JSON.parse(cInc);renderSavedIncidents();}catch(e){}const cb='jsonpInit_'+Math.round(100000*Math.random());window[cb]=function(d){try{if(d&&d.status==="success"){globalFleetData=d.fleet?d.fleet.reverse():[];globalSurveys=d.surveys?d.surveys.reverse():[];globalUsers=d.users||[];if(d.incidents&&d.incidents.length>0){globalIncidents=d.incidents;localStorage.setItem('rmf_incidents',JSON.stringify(globalIncidents));}globalDirectory=d.directory||[];globalFod=d.fod||[];globalSpiData=d.spi||[];sortIncidentsByDate();if(d.daily&&d.daily.length>0){let rMap={};d.daily.forEach(row=>{let repId=row.Report_ID,timeStr=row.Time;if(timeStr&&typeof timeStr==='string'&&timeStr.includes('T')){let dt=new Date(timeStr);if(!isNaN(dt))timeStr=dt.toISOString().substring(11,16);}if(!rMap[repId])rMap[repId]={id:repId,date:row.Date?new Date(row.Date).toISOString().split('T')[0]:'',time:timeStr,shift:row.Shift,inspector:row.Inspector,findings:[]};if(row.Category&&row.Category!=="لا توجد ملاحظات")rMap[repId].findings.push({category:row.Category,item:row.Finding_Item,location:row.Location,responsible:row.Responsible,note:row.Corrective_Action||"",status:row.Status||"مفتوح"});});globalDailyInspections=Object.values(rMap).sort((a,b)=>b.id-a.id);}populateUsersDropdown(globalUsers);renderDirectory();updateSurveyNavCounter();buildSpiEntryForm();renderSavedDaily();renderSavedIncidents();updateDailyNavCounter();}}catch(e){console.error(e);}finally{delete window[cb];}};const s=document.createElement('script');s.src=API_URL+"?action=getAppData&_t="+Date.now()+"&callback="+cb;document.body.appendChild(s);}

// دالة فرز سجل الوقائع بالتاريخ من الأحدث إلى الأقدم
function sortIncidentsByDate(){if(!globalIncidents)return;globalIncidents.sort((a,b)=>{let da=new Date(a.Date||a.date||0).getTime(),db=new Date(b.Date||b.date||0).getTime();return db-da;});}

// دالة تحديث عداد التنقل في استبيان الطيارين
function updateSurveyNavCounter(){const el=document.getElementById('nav-counter');if(el)el.innerText=globalSurveys.length>0?`${currentSurveyIndex+1} / ${globalSurveys.length}`:`0 / 0`;}

// دالة التنقل بين استبيانات الطيارين
function navSurveys(dir){if(!globalSurveys||globalSurveys.length===0)return alert("لا توجد استبيانات مسجلة بعد.");if(dir==='first')currentSurveyIndex=0;else if(dir==='last')currentSurveyIndex=globalSurveys.length-1;else if(dir==='next'&&currentSurveyIndex<globalSurveys.length-1)currentSurveyIndex++;else if(dir==='prev'&&currentSurveyIndex>0)currentSurveyIndex--;if(currentSurveyIndex>=0&&currentSurveyIndex<globalSurveys.length){displaySurveyInForm(globalSurveys[currentSurveyIndex]);updateSurveyNavCounter();let b=document.getElementById('submitSurveyBtn');if(b){b.disabled=true;b.innerHTML='<i class="fa-solid fa-eye"></i> وضع العرض';b.style.backgroundColor="#6c757d";}}}

// دالة عرض بيانات استبيان محدد في النموذج
function displaySurveyInForm(s){if(!s)return;document.getElementById('capDate').value=s.Date?new Date(s.Date).toISOString().split('T')[0]:'';let tVal=s.Time||'';document.getElementById('capTime').value=tVal.includes('T')?new Date(tVal).toTimeString().substring(0,5):tVal;document.getElementById('fltNo').value=s.Flight_NO||'';document.getElementById('reg').value=s.REG||'';document.getElementById('airline').value=s.CAR||'';document.getElementById('acType').value=s.TYPE||'';document.getElementById('comments').value=s.Captain_Comments||'';criteriaList.forEach(c=>{let v=s[c]||"Blank",r=document.querySelector(`input[name="${c}"][value="${v}"]`);if(r)r.checked=true;});}

// دالة تفريغ نموذج الاستبيان لإضافة استبيان جديد
function clearFormForNew(){currentSurveyIndex=-1;document.getElementById('surveyForm').reset();updateSurveyNavCounter();let b=document.getElementById('submitSurveyBtn');if(b){b.disabled=false;b.innerHTML='<i class="fa-solid fa-cloud-arrow-up"></i> حفظ بيانات الاستبيان';b.style.backgroundColor="var(--primary)";}let now=new Date().toISOString();document.getElementById('capDate').value=now.split('T')[0];document.getElementById('capTime').value=now.split('T')[1].substring(0,5);}

// دالة إرسال وحفظ استبيان الطيارين
function submitSurvey(e){e.preventDefault();const btn=document.getElementById('submitSurveyBtn'),msg=document.getElementById('surveyMsg'),airline=document.getElementById('airline').value;if(!airline)return;let sObj={"Date":document.getElementById('capDate').value,"Time":document.getElementById('capTime').value,"Flight_NO":document.getElementById('fltNo').value,"REG":document.getElementById('reg').value.toUpperCase(),"CAR":airline,"TYPE":document.getElementById('acType').value,"Captain_Comments":document.getElementById('comments').value};criteriaList.forEach(crit=>{let sel=document.querySelector(`input[name="${crit}"]:checked`);sObj[crit]=sel?sel.value:"Blank";});safePost({action:"submitSurvey",surveyData:sObj},btn,msg,"تم الحفظ بنجاح!",()=>{globalSurveys.unshift(sObj);updateSurveyNavCounter();setTimeout(()=>clearFormForNew(),1500);});}

// دالة بناء عناصر تقييم استبيان الطيارين الـ 31 بند
function buildEvaluationForm(){const c=document.getElementById('criteria-container');if(!c)return;c.innerHTML='';criteriaList.forEach((crit,idx)=>{c.innerHTML+=`<div class="eval-card"><div class="eval-title">${crit}</div><div class="radio-group"><input type="radio" id="c${idx}_e" name="${crit}" value="Excellent" checked><label for="c${idx}_e" class="lbl-e">E</label><input type="radio" id="c${idx}_g" name="${crit}" value="Good"><label for="c${idx}_g" class="lbl-g">G</label><input type="radio" id="c${idx}_p" name="${crit}" value="Poor"><label for="c${idx}_p" class="lbl-p">P</label><input type="radio" id="c${idx}_n" name="${crit}" value="N/A"><label for="c${idx}_n" class="lbl-n">N/A</label><input type="radio" id="c${idx}_b" name="${crit}" value="Blank"><label for="c${idx}_b" class="lbl-b">B</label></div></div>`;});}

// دالة التبديل بين تبويبات استبيان الطيارين
function switchTab(t){document.querySelectorAll('#captain-survey-section .tab-btn').forEach(b=>b.classList.remove('active'));document.querySelectorAll('#captain-survey-section .tab-content').forEach(c=>c.classList.remove('active'));document.getElementById('btn-'+t)?.classList.add('active');document.getElementById('tab-'+t)?.classList.add('active');}

// دالة إعداد القائمة المنسدلة لحروف تسجيل الطائرات
function setupCustomDropdown(){const inp=document.getElementById('reg'),arr=document.getElementById('regArrowBtn'),lst=document.getElementById('regDropdownList');if(inp&&arr&&lst){arr.addEventListener('click',e=>{e.stopPropagation();lst.classList.toggle('show');filterRegOptions(true);});inp.addEventListener('input',()=>{lst.classList.add('show');filterRegOptions(false);});document.addEventListener('click',()=>lst.classList.remove('show'));}}

// دالة فلترة واختيار حروف تسجيل الطائرات من الأسطول
function filterRegOptions(all){const inp=document.getElementById('reg'),lst=document.getElementById('regDropdownList');let val=inp.value.toUpperCase();lst.innerHTML='';let m=all?globalFleetData:globalFleetData.filter(a=>String(a.REG).toUpperCase().includes(val));m.forEach(a=>{let d=document.createElement('div');d.className='custom-dropdown-item';d.innerHTML=`${a.REG} <span style="font-size:0.75rem;color:#777;float:right;">${a.CAR}</span>`;d.onclick=()=>{inp.value=a.REG;document.getElementById('airline').value=a.CAR||"";document.getElementById('acType').value=a.TYPE||"";lst.classList.remove('show');};lst.appendChild(d);});}

// دالة إصدار تقرير استبيان الطيارين الحديث بالشارتات
function generateModernReport(){let fromD=document.getElementById('fromDate').value,toD=document.getElementById('toDate').value;if(!fromD||!toD)return alert("اختر الفترة أولاً");let fd=new Date(fromD),td=new Date(toD);td.setHours(23,59,59,999);document.getElementById('printable-report').style.display='block';let flt=globalSurveys.filter(s=>{let sd=new Date(s.Date);return sd>=fd&&sd<=td;});document.getElementById('report-date-range').innerText=`الفترة من ${fromD} إلى ${toD}`;document.getElementById('stat-total').innerText=flt.length;let aC={},dC={},eC={"Excellent":0,"Good":0,"Poor":0,"N/A":0,"Blank":0},cList=[];const tb=document.getElementById('flights-eval-tbody');tb.innerHTML='';let mS={"Excellent":{},"Good":{},"Poor":{},"N/A":{},"Blank":{}};criteriaList.forEach(crit=>{mS["Excellent"][crit]=0;mS["Good"][crit]=0;mS["Poor"][crit]=0;mS["N/A"][crit]=0;mS["Blank"][crit]=0;});flt.forEach(s=>{if(s.CAR)aC[s.CAR]=(aC[s.CAR]||0)+1;let ds=s.Date?String(s.Date).split('T')[0]:'Unknown';dC[ds]=(dC[ds]||0)+1;let fC={"Excellent":0,"Good":0,"Poor":0,"N/A":0,"Blank":0};criteriaList.forEach(crit=>{let v=s[crit]||"Blank";if(fC[v]!==undefined)fC[v]++;if(eC[v]!==undefined)eC[v]++;if(mS[v])mS[v][crit]++;});if(s.Captain_Comments&&s.Captain_Comments.trim()!=="")cList.push(s);tb.innerHTML+=`<tr><td><b>${s.CAR||''}</b></td><td>${s.Flight_NO||''}</td><td>${ds}</td><td>${s.REG||''}</td><td style="color:#28a745;font-weight:bold;">${fC["Excellent"]}</td><td style="color:#ffc107;font-weight:bold;">${fC["Good"]}</td><td style="color:#dc3545;font-weight:bold;">${fC["Poor"]}</td><td>${fC["N/A"]}</td><td>${fC["Blank"]}</td></tr>`;});document.getElementById('stat-airlines').innerText=Object.keys(aC).length;let totE=Object.values(eC).reduce((a,b)=>a+b,0);document.getElementById('stat-excellent').innerText=`${totE>0?Math.round((eC["Excellent"]/totE)*100):0}%`;if(chartInstances.air)chartInstances.air.destroy();if(chartInstances.dates)chartInstances.dates.destroy();if(chartInstances.eval)chartInstances.eval.destroy();Chart.defaults.font.family="'Cairo', sans-serif";chartInstances.air=new Chart(document.getElementById('airlinesChart').getContext('2d'),{type:'bar',data:{labels:Object.keys(aC),datasets:[{label:'الاستبيانات',data:Object.values(aC),backgroundColor:'#003366',borderRadius:4}]},options:{responsive:true,maintainAspectRatio:false}});chartInstances.dates=new Chart(document.getElementById('datesChart').getContext('2d'),{type:'line',data:{labels:Object.keys(dC).sort(),datasets:[{label:'النشاط اليومي',data:Object.keys(dC).sort().map(d=>dC[d]),borderColor:'#f39c12',tension:0.3}]},options:{responsive:true,maintainAspectRatio:false}});chartInstances.eval=new Chart(document.getElementById('evalChart').getContext('2d'),{type:'doughnut',data:{labels:['Excellent','Good','Poor','N/A','Blank'],datasets:[{data:Object.values(eC),backgroundColor:['#28a745','#ffc107','#dc3545','#6c757d','#003366']}]},options:{responsive:true,maintainAspectRatio:false}});let eH=`<div class="avoid-page-break" style="margin-top:35px;direction:ltr;"><h3 style="color:#003366;text-align:center;margin-bottom:12px;font-size:1.2rem;">Safety Captain Survey Report Evaluation Matrix</h3><table style="width:100%;border-collapse:collapse;border:1px solid #777;font-size:11px;text-align:center;"><thead><tr style="background:#003366;color:#fff;"><th style="padding:8px;border:1px solid #999;text-align:left;width:40%;">Evaluation Criteria</th><th style="padding:8px;border:1px solid #999;background:#28a745;">Excellent</th><th style="padding:8px;border:1px solid #999;background:#ffc107;color:#000;">Good</th><th style="padding:8px;border:1px solid #999;background:#dc3545;">Poor</th><th style="padding:8px;border:1px solid #999;background:#6c757d;">N/A</th><th style="padding:8px;border:1px solid #999;background:#1a2a6c;">Blank</th></tr></thead><tbody>`;criteriaList.forEach(crit=>{eH+=`<tr><td style="padding:6px 10px;border:1px solid #ccc;text-align:left;font-weight:bold;background:#f9f9f9;">${crit}</td><td style="padding:6px;border:1px solid #ccc;font-weight:bold;color:${mS["Excellent"][crit]>0?'#28a745':'#aaa'};">${mS["Excellent"][crit]||0}</td><td style="padding:6px;border:1px solid #ccc;font-weight:bold;color:${mS["Good"][crit]>0?'#ffc107':'#aaa'};">${mS["Good"][crit]||0}</td><td style="padding:6px;border:1px solid #ccc;font-weight:bold;color:${mS["Poor"][crit]>0?'#dc3545':'#aaa'};">${mS["Poor"][crit]||0}</td><td style="padding:6px;border:1px solid #ccc;color:#555;">${mS["N/A"][crit]||0}</td><td style="padding:6px;border:1px solid #ccc;color:#555;">${mS["Blank"][crit]||0}</td></tr>`;});eH+=`</tbody></table></div><div class="avoid-page-break" style="margin-top:35px;direction:ltr;text-align:left;"><h3 style="color:#003366;margin-bottom:10px;">Captain Comments & Observations:</h3><table class="avoid-page-break" style="width:100%;border-collapse:collapse;border:1px solid #000;font-size:11px;"><thead style="background:#e6e6e6;"><tr><th style="border:1px solid #000;padding:6px;">Airline</th><th style="border:1px solid #000;padding:6px;">FLTNO</th><th style="border:1px solid #000;padding:6px;">Type</th><th style="border:1px solid #000;padding:6px;">Date</th><th style="border:1px solid #000;padding:6px;">REG</th><th style="border:1px solid #000;padding:6px;">Comments</th></tr></thead><tbody>`;if(cList.length===0)eH+=`<tr><td colspan="6" style="text-align:center;">No comments.</td></tr>`;else cList.forEach(s=>{eH+=`<tr><td style="border:1px solid #000;padding:6px;">${s.CAR||'-'}</td><td style="border:1px solid #000;padding:6px;">${s.Flight_NO||'-'}</td><td style="border:1px solid #000;padding:6px;">${s.TYPE||'-'}</td><td style="border:1px solid #000;padding:6px;">${s.Date?String(s.Date).split('T')[0]:''}</td><td style="border:1px solid #000;padding:6px;">${s.REG||'-'}</td><td style="border:1px solid #000;padding:6px;">${s.Captain_Comments}</td></tr>`;});eH+=`</tbody></table></div>`;document.getElementById('additional-tables-container').innerHTML=eH;}

// دالة تصدير تقرير الاستبيانات PDF
function exportModernPDF(){html2pdf().set({margin:0.3,filename:'Captain_Surveys_Report.pdf',image:{type:'jpeg',quality:1},html2canvas:{scale:2},jsPDF:{orientation:'portrait',unit:'in',format:'a4'},pagebreak:{mode:'css',avoid:['tr','table','.avoid-page-break']}}).from(document.getElementById('printable-report')).save();}

// دالة إنشاء مصفوفة الفحص اليومي 
function buildDailyChecklist(){const g=document.getElementById('checklist-container');if(!g)return;g.innerHTML="";let cI=0;Object.keys(dailyChecklistDataISO).forEach(k=>{let d=dailyChecklistDataISO[k],h=`<div class="checklist-column">`;const rS=(t,items)=>{h+=`<div class="checklist-header">${t}</div>`;items.forEach(it=>{let opts=responsibleDepts.map(dp=>`<option value="${dp}">${dp}</option>`).join('');h+=`<div class="check-item"><div class="check-item-row"><input type="checkbox" id="chk_${cI}" value="${t}|${it}" onchange="toggleInputs(${cI})"><label for="chk_${cI}">${it}</label></div><div id="inputs_${cI}" class="check-inputs"><input type="text" id="note_${cI}" placeholder="تفاصيل الملاحظة..."><div style="display:flex;gap:5px;"><input type="text" id="loc_${cI}" placeholder="المكان..." style="flex:1;"><select id="resp_${cI}" style="flex:1;"><option value="" disabled selected>الجهة...</option>${opts}</select></div></div></div>`;cI++;});};rS(d.title,d.items);if(d.title2)rS(d.title2,d.items2);if(d.title3)rS(d.title3,d.items3);h+=`</div>`;g.innerHTML+=h;});}

// دالة تبديل حقول تفاصيل ملاحظة الفحص اليومي
window.toggleInputs=function(idx){const chk=document.getElementById('chk_'+idx),inps=document.getElementById('inputs_'+idx);if(chk&&inps)inps.style.display=chk.checked?'flex':'none';};

// دالة التبديل بين تبويبات الفحص اليومي
function switchDailyTab(tab){document.querySelectorAll('#daily-inspection-section .tab-btn').forEach(b=>b.classList.remove('active'));document.querySelectorAll('#daily-inspection-section .tab-content').forEach(c=>c.classList.remove('active'));document.getElementById('btn-daily-'+tab)?.classList.add('active');document.getElementById('tab-daily-'+tab)?.classList.add('active');}

// دالة تحديث عداد جولات التفتيش اليومية
function updateDailyNavCounter(){const el=document.getElementById('nav-daily-counter');if(el)el.innerText=globalDailyInspections.length>0?`${currentDailyIndex+1} / ${globalDailyInspections.length}`:`0 / 0`;}

// دالة تفريغ نموذج التفتيش اليومي لإنشاء جولة جديدة
function clearDailyFormForNew(){currentDailyIndex=-1;isDailyEditMode=false;currentDailyEditId=null;document.getElementById('dailyForm').reset();document.querySelectorAll('#checklist-container input[type="checkbox"]').forEach(c=>c.checked=false);document.querySelectorAll('.check-inputs').forEach(el=>el.style.display='none');let b=document.getElementById('submitDailyBtn');if(b){b.innerHTML='<i class="fa-solid fa-cloud-arrow-up"></i> حفظ الجولة';b.style.backgroundColor="var(--primary)";}let now=new Date().toISOString();document.getElementById('dailyDate').value=now.split('T')[0];document.getElementById('dailyTime').value=now.split('T')[1].substring(0,5);updateDailyNavCounter();}

// دالة التنقل بين جولات التفتيش اليومية بدون قفز أو ترحيل للشاشة
function navDaily(dir){if(!globalDailyInspections||globalDailyInspections.length===0)return alert("لا توجد فحوصات مسجلة.");if(dir==='first')currentDailyIndex=0;else if(dir==='last')currentDailyIndex=globalDailyInspections.length-1;else if(dir==='next'&&currentDailyIndex<globalDailyInspections.length-1)currentDailyIndex++;else if(dir==='prev'&&currentDailyIndex>0)currentDailyIndex--;if(currentDailyIndex>=0&&currentDailyIndex<globalDailyInspections.length)loadDailyInspectionToForm(currentDailyIndex);}

// دالة تحميل جولة تفتيش محددة في النموذج للتعديل مع ثبات موضع الشاشة
function loadDailyInspectionToForm(idx){if(idx<0||idx>=globalDailyInspections.length)return;currentDailyIndex=idx;isDailyEditMode=true;let rep=globalDailyInspections[idx];currentDailyEditId=rep.id;document.getElementById('dailyDate').value=rep.date||'';document.getElementById('dailyTime').value=rep.time||'';document.getElementById('dailyShift').value=rep.shift||'صباحي';document.getElementById('dailyInspector').value=rep.inspector||'';document.querySelectorAll('#checklist-container input[type="checkbox"]').forEach(c=>c.checked=false);document.querySelectorAll('.check-inputs').forEach(el=>{el.style.display='none';el.querySelectorAll('input').forEach(inp=>inp.value='');});if(rep.findings&&rep.findings.length>0){rep.findings.forEach(f=>{document.querySelectorAll('#checklist-container input[type="checkbox"]').forEach((chk,cIdx)=>{let p=chk.value.split('|');if(p[0]===f.category&&p[1]===f.item){chk.checked=true;toggleInputs(cIdx);let n=document.getElementById(`note_${cIdx}`),l=document.getElementById(`loc_${cIdx}`),r=document.getElementById(`resp_${cIdx}`);if(n)n.value=f.note||f.Corrective_Action||'';if(l)l.value=f.location||f.Location||'';if(r)r.value=f.responsible||f.Responsible||'';}});});}let btn=document.getElementById('submitDailyBtn');if(btn){btn.innerHTML='<i class="fa-solid fa-pen-to-square"></i> تحديث';btn.style.backgroundColor="#e67e22";}updateDailyNavCounter();}

// دالة حفظ وتحديث جولة الفحص اليومي
function submitDailyInspection(e){if(e)e.preventDefault();const btn=document.getElementById('submitDailyBtn'),msg=document.getElementById('dailyMsg');let fList=[];document.querySelectorAll('#checklist-container input[type="checkbox"]').forEach((chk,idx)=>{if(chk.checked){let p=chk.value.split('|');fList.push({category:p[0],item:p[1],location:document.getElementById(`loc_${idx}`).value||"-",responsible:document.getElementById(`resp_${idx}`).value||"-",note:document.getElementById(`note_${idx}`).value||"تالف",status:"مفتوح"});}});let repId=isDailyEditMode&&currentDailyEditId?currentDailyEditId:Date.now();let rep={id:repId,date:document.getElementById('dailyDate').value,time:document.getElementById('dailyTime').value,shift:document.getElementById('dailyShift').value,inspector:document.getElementById('dailyInspector').value,findings:fList};safePost({action:isDailyEditMode?"updateDailyInspection":"submitDailyInspection",reportData:rep},btn,msg,"تم الحفظ بنجاح!",()=>{if(isDailyEditMode){let eIdx=globalDailyInspections.findIndex(r=>String(r.id)===String(repId));if(eIdx!==-1)globalDailyInspections[eIdx]=rep;}else{globalDailyInspections.unshift(rep);}renderSavedDaily();setTimeout(()=>clearDailyFormForNew(),1500);});}

// دالة عرض جدول جولات التفتيش المحفوظة
function renderSavedDaily(){const tb=document.getElementById('saved-daily-tbody');if(!tb)return;tb.innerHTML="";globalDailyInspections.forEach((rep,idx)=>{let cnt=rep.findings?rep.findings.length:0,bdg=cnt>0?`<span style="color:#dc3545;font-weight:bold;">${cnt} ملاحظة</span>`:`<span style="color:#28a745;font-weight:bold;">سليم</span>`;let rDt=(rep.date||'').toString().split('T')[0];tb.innerHTML+=`<tr style="text-align:center;border-bottom:1px solid #ddd;"><td dir="ltr" style="padding:8px;">${rDt||'-'}</td><td style="padding:8px;">${rep.time||'-'}</td><td style="padding:8px;">${rep.shift||'-'}</td><td style="padding:8px;">${rep.inspector||'-'}</td><td style="padding:8px;">${bdg}</td><td style="padding:6px;display:flex;gap:5px;justify-content:center;"><button type="button" onclick="loadDailyInspectionToForm(${idx})" style="background:#003366;color:#fff;border:none;padding:5px 10px;border-radius:4px;cursor:pointer;font-weight:bold;"><i class="fa-solid fa-pen"></i> تعديل</button><button type="button" onclick="printDailyIsoDirect('${rDt}','${rep.shift||''}')" style="background:#28a745;color:#fff;border:none;padding:5px 10px;border-radius:4px;cursor:pointer;font-weight:bold;"><i class="fa-solid fa-print"></i> ISO</button><button type="button" onclick="deleteDailyInspectionRecord(${idx})" style="background:#dc3545;color:#fff;border:none;padding:5px 8px;border-radius:4px;cursor:pointer;"><i class="fa-solid fa-trash"></i></button></td></tr>`;});const dInp=document.getElementById('isoReportDate');if(dInp&&!dInp.value)dInp.value=new Date().toISOString().split('T')[0];}

// دالة إصدار وعرض نموذج الفحص اليومي AS-F-01-01 المعتمد
function printDailyIsoDirect(dt,shift){const dInp=document.getElementById('isoReportDate'),sInp=document.getElementById('isoReportShift');if(dInp&&dt)dInp.value=dt;if(sInp&&shift)sInp.value=shift;generateIsoDailyReport();const repEl=document.getElementById('printable-daily-report');if(repEl)repEl.scrollIntoView({behavior:'smooth'});}

// دالة حذف جولة تفتيش يومية
function deleteDailyInspectionRecord(idx){if(!confirm("تأكيد الحذف؟"))return;let repId=globalDailyInspections[idx].id;globalDailyInspections.splice(idx,1);renderSavedDaily();updateDailyNavCounter();safePost({action:"updateDailyInspection",reportData:{id:repId,findings:[]}});}

// دالة إصدار وطباعة نموذج التفتيش اليومي المعتمد AS-F-01-01
function generateIsoDailyReport(){let targetD=document.getElementById('isoReportDate')?.value;let targetS=document.getElementById('isoReportShift')?.value||'صباحي';if(!targetD&&globalDailyInspections.length>0){targetD=String(globalDailyInspections[0].date).split('T')[0];targetS=globalDailyInspections[0].shift||'صباحي';document.getElementById('isoReportDate').value=targetD;document.getElementById('isoReportShift').value=targetS;}let rep=globalDailyInspections.find(r=>String(r.date).split('T')[0]===targetD&&(r.shift||'صباحي')===targetS)||globalDailyInspections[0];if(!rep){alert("لا توجد جولة تفتيش محفوظة بهذا التاريخ وهذه الوردية!");return;}document.getElementById('iso-date-val').innerText=(targetD||String(rep.date).split('T')[0]).split('-').reverse().join(' / ');document.getElementById('iso-shift-am').innerHTML=targetS==='صباحي'?'✔':'';document.getElementById('iso-shift-pm').innerHTML=targetS!=='صباحي'?'✔':'';let fList=rep.findings||[];const mat=document.getElementById('iso-matrix-container');mat.innerHTML="";let maxC=0;Object.keys(dailyChecklistDataISO).forEach(k=>{let c=dailyChecklistDataISO[k],cnt=(c.items?c.items.length:0)+(c.items2?c.items2.length:0)+(c.items3?c.items3.length:0)+1+(c.title2?1:0)+(c.title3?1:0);if(cnt>maxC)maxC=cnt;});const flat={};Object.keys(dailyChecklistDataISO).forEach(k=>{let c=dailyChecklistDataISO[k],arr=[];const inj=(t,items)=>{arr.push({isH:true,txt:t});items.forEach(it=>{let hasF=fList.some(f=>(f.category||"").trim()===t.trim()&&(f.item||"").trim()===it.trim());arr.push({isH:false,txt:it,safe:!hasF});});};inj(c.title,c.items);if(c.title2)inj(c.title2,c.items2);if(c.title3)inj(c.title3,c.items3);flat[k]=arr;});let mH="";for(let r=0;r<maxC;r++){Object.keys(dailyChecklistDataISO).forEach(k=>{let cd=flat[k][r];if(cd){if(cd.isH){mH+=`<div style="border:1px solid #000;background:#e6e6e6;padding:4px;font-weight:bold;text-align:center;">${cd.txt}</div>`;}else{let sign=cd.safe?"✔":"✘",clr=cd.safe?"#000":"#dc3545",dec=cd.safe?"none":"line-through";mH+=`<div style="border:1px solid #000;padding:3px 5px;display:flex;justify-content:space-between;align-items:center;background:#fff;"><span style="color:${clr};text-decoration:${dec};font-weight:${cd.safe?'normal':'bold'};">${cd.txt}</span><span style="display:inline-block;width:12px;height:12px;border:1px solid #000;text-align:center;line-height:10px;font-size:10px;font-weight:bold;color:${clr};">${sign}</span></div>`;}}else{mH+=`<div style="border:1px solid #000;background:#fff;"></div>`;}});}mat.innerHTML=mH;const fTb=document.getElementById('iso-findings-tbody');fTb.innerHTML="";if(fList.length===0){fTb.innerHTML=`<tr><td colspan="5" style="border:1px solid #000;padding:12px;text-align:center;color:green;font-weight:bold;font-size:1.1rem;">المنطقة مطابقة وسليمة (لا توجد ملاحظات)</td></tr>`;}else{fList.forEach((f,i)=>{fTb.innerHTML+=`<tr><td style="border:1px solid #000;padding:6px;">${i+1}</td><td style="border:1px solid #000;padding:6px;">${f.location||'-'}</td><td style="border:1px solid #000;padding:6px;text-align:right;color:#dc3545;font-weight:bold;">${f.category} - ${f.item} <br> <span style="color:#333;font-weight:normal;">(${f.note||'ملاحظة'})</span></td><td style="border:1px solid #000;padding:6px;">${f.responsible||'-'}</td><td style="border:1px solid #000;padding:6px;color:#dc3545;font-weight:bold;">مفتوح</td></tr>`;});}document.getElementById('printable-daily-report').style.display='block';}

// دالة تصدير نموذج الفحص اليومي AS-F-01-01 كصورة عريضة لاندسكيب عالية الجودة PNG
function exportIsoform(){let el=document.getElementById('printable-daily-report');const rDate=document.getElementById('isoReportDate')?.value||new Date().toISOString().split('T')[0];const rShift=document.getElementById('isoReportShift')?.value||'صباحي';if(!el||el.style.display==='none'){if(typeof generateIsoDailyReport==='function')generateIsoDailyReport();el=document.getElementById('printable-daily-report');}if(!el||el.style.display==='none')return alert("يرجى اختيار التاريخ والوردية المحفوظة أولاً لعرض التقرير!");window.scrollTo(0,0);if(typeof html2canvas!=='undefined'){html2canvas(el,{scale:2,useCORS:true,allowTaint:true,backgroundColor:'#ffffff',logging:false}).then(cvs=>{cvs.toBlob(blob=>{if(!blob)return window.print();let u=URL.createObjectURL(blob),a=document.createElement('a');a.download=`Daily_Inspection_AS_F_01_01_${rDate}_${rShift}.png`;a.href=u;document.body.appendChild(a);a.click();setTimeout(()=>{document.body.removeChild(a);URL.revokeObjectURL(u);},1000);},'image/png');}).catch(e=>{console.warn(e);window.print();});}else{window.print();}}

// دالة مطابقة لتصدير نموذج الفحص اليومي لضمان عمل كافة الأزرار
function exportIsoDailyPDF(){exportIsoform();}

// دالة التبديل بين تبويبات سجل الحوادث والوقائع مع إعادة رسم الجدول فوراً
function switchIncidentTab(t){document.querySelectorAll('#incident-section .tab-btn').forEach(b=>b.classList.remove('active'));document.querySelectorAll('#incident-section .tab-content').forEach(c=>c.classList.remove('active'));document.getElementById('btn-inc-'+t)?.classList.add('active');document.getElementById('tab-inc-'+t)?.classList.add('active');if(t==='monthly')renderSavedIncidents();}

// دالة تفريغ نموذج إدخال الواقعة لإضافة واقعة جديدة
function clearIncidentForm(){currentIncidentIndex=-1;currentIncidentEditId=null;const f=document.getElementById('incidentForm');if(f)f.reset();const idF=document.getElementById('incId');if(idF)idF.value='';const dtF=document.getElementById('incDate');if(dtF)dtF.value=new Date().toISOString().split('T')[0];const b=document.getElementById('submitIncBtn');if(b){b.innerHTML='<i class="fa-solid fa-cloud-arrow-up"></i> حفظ الواقعة وتحديث السجل';b.style.backgroundColor='#dc3545';}}

// دالة حفظ وتحديث الواقعة في السيرفر وتحديث الجدول بالفرز والصفحات تلقائياً
async function saveIncident(e){if(e){e.preventDefault();e.stopPropagation();}const btn=document.getElementById('submitIncBtn')||event?.target?.closest('button');if(btn){btn.disabled=true;btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> جاري الحفظ...';}const g=(id)=>document.getElementById(id)?.value?.trim()||'';const date=g('incDate')||new Date().toISOString().split('T')[0];const desc=g('incDesc')||'-';const incId=currentIncidentEditId||g('incId')||("INC-"+Date.now());const incObj={id:incId,date:date,time:g('incTime')||'',location:g('incLocation')||'Apron',personnel:g('incPersonnel')||'Nil',equipmentNo:g('incEquipmentNo')||'Nil',driver:g('incDriver')||'Nil',eqOwner:g('incEqOwner')||'EMAAS handling company',status:g('incStatus')||'In service',causes:g('incCauses')||'Human Causes',charaterization:g('incChar')||'Equipment Accident',riskSeverity:g('incRiskSev')||'Minor',riskProb:g('incRiskProb')||'Remote',checkboxes:'',car:g('incCar')||'-',flightNo:g('incFlightNo')||'-',reg:g('incReg')||'-',orgVia:'-',viaDst:'-',preparedBy:g('incPreparedBy')||'Samy Lukas',hazardDesc:g('incHazardDesc')||'-',description:desc,actionTaken:g('incAction')||'-',recommendation:g('incRecommendation')||'-',attachment_URL:g('incAttach')||'',position:g('incPosition')||'Nil',injuryType:g('incInjuryType')||'Nil',causesDetails:g('incCausesDetails')||'-',type:g('incAcType')||'-'};try{await fetch(API_URL,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:currentIncidentEditId?"updateIncident":"submitIncident",incidentData:incObj})});if(!window.globalIncidents)window.globalIncidents=[];let exIdx=window.globalIncidents.findIndex(x=>(x.ID||x.id)===incId);let mapped={ID:incObj.id,Date:incObj.date,Time:incObj.time,Location:incObj.location,Personnel_Involved:incObj.personnel,Equipment_No:incObj.equipmentNo,Driver_Name:incObj.driver,Equipment_Owned:incObj.eqOwner,Status:incObj.status,Occurrence_Causes:incObj.causes,Characterization:incObj.charaterization,Risk_Severity:incObj.riskSeverity,Risk_Probability:incObj.riskProb,Checkboxes:'',CAR:incObj.car,Flight_No:incObj.flightNo,REG:incObj.reg,Prepared_By:incObj.preparedBy,Hazard_Description:incObj.hazardDesc,Description:incObj.description,Action_Taken:incObj.actionTaken,Recommendation:incObj.recommendation,Attachment_URL:incObj.attachment_URL,Position:incObj.position,Injury_Type:incObj.injuryType,Causes_Details:incObj.causesDetails,TYPE:incObj.type};if(exIdx>-1)window.globalIncidents[exIdx]=mapped;else window.globalIncidents.unshift(mapped);try{localStorage.setItem('rmf_incidents',JSON.stringify(window.globalIncidents));}catch(e){}sortIncidentsByDate();alert('✅ تم حفظ الواقعة بنجاح وتحديث قاعدة البيانات!');clearIncidentForm();renderSavedIncidents();switchIncidentTab('monthly');}catch(err){console.error(err);alert('❌ حدث خطأ أثناء الاتصال بالسيرفر لحفظ الواقعة.');}finally{if(btn)btn.disabled=false;}}

// دالة رسم جدول الوقائع المسجلة بفرز التاريخ وأزرار التحكم الأربعة بدون ترحيل للشاشة
function renderSavedIncidents(){const tb=document.getElementById('saved-inc-tbody')||document.querySelector('#incident-section table tbody');sortIncidentsByDate();const list=window.globalIncidents||[];const totalPages=Math.ceil(list.length/incPageSize)||1;if(incCurrentPage>totalPages)incCurrentPage=totalPages;if(incCurrentPage<1)incCurrentPage=1;bindIncPaginationButtons();if(!tb)return;const start=(incCurrentPage-1)*incPageSize,paged=list.slice(start,start+incPageSize);tb.innerHTML='';if(paged.length===0){tb.innerHTML='<tr><td colspan="6" style="text-align:center;padding:15px;color:#777;">لا توجد وقائع مسجلة حالياً</td></tr>';return;}paged.forEach((item,idx)=>{const id=item.ID||item.id||`INC-${idx}`;const dt=(item.Date||item.date||'').toString().split('T')[0];const loc=item.Location||item.location||'-';const flt=item.Flight_No||item.flightNo||item.CAR||'';const locFlt=flt?`${loc} / ${flt}`:loc;const char=item.Characterization||item.charaterization||item.characterization||'-';const sev=item.Risk_Severity||item.riskSeverity||'-';const loss=item.Prepared_By||item.preparedBy||item.Personnel_Involved||'-';const sClr=sev==='Catastrophic'||sev==='Critical'?'#dc3545':(sev==='Major'?'#ffc107':'#28a745');tb.innerHTML+=`<tr style="border-bottom:1px solid #ddd;text-align:center;"><td style="padding:8px;" dir="ltr">${dt}</td><td style="padding:8px;font-weight:bold;">${locFlt}</td><td style="padding:8px;">${char}</td><td style="padding:8px;"><span style="background:${sClr};color:#fff;padding:2px 8px;border-radius:4px;font-size:11px;">${sev}</span></td><td style="padding:8px;">${loss}</td><td style="padding:6px;display:flex;gap:4px;justify-content:center;align-items:center;"><button type="button" onclick="editIncident('${id}')" title="عرض وتعديل الواقعة" style="background:#17a2b8;color:#fff;border:none;padding:5px 8px;border-radius:4px;cursor:pointer;"><i class="fa-solid fa-pen-to-square"></i></button><button type="button" onclick="printIsoIncidentReport('${id}')" title="طباعة تقرير ISO" style="background:#003366;color:#fff;border:none;padding:5px 8px;border-radius:4px;cursor:pointer;"><i class="fa-solid fa-print"></i></button><button type="button" onclick="exportIsoIncidentImage('${id}')" title="تصدير كصورة عريضة PNG" style="background:#28a745;color:#fff;border:none;padding:5px 8px;border-radius:4px;cursor:pointer;"><i class="fa-solid fa-file-image"></i></button><button type="button" onclick="deleteIncident('${id}')" title="حذف الواقعة" style="background:#dc3545;color:#fff;border:none;padding:5px 8px;border-radius:4px;cursor:pointer;"><i class="fa-solid fa-trash"></i></button></td></tr>`;});}

// دالة متطابقة مع دالة عرض الجدول لضمان التوافق البرمجي الكامل
function renderIncidentsTable(){renderSavedIncidents();}

// دالة ربط أزرار النافيجيشن « ‹ › » تلقائياً وتحديث مؤشر الصفحات بدون قفز
function bindIncPaginationButtons(){const sec=document.getElementById('incident-section')||document;const btns=Array.from(sec.querySelectorAll('button')).filter(b=>['«','‹','›','»','<<','<','>','>>'].includes(b.innerText.trim()));if(btns.length>=4){btns[0].onclick=(e)=>{e.preventDefault();changeIncPage('first');};btns[1].onclick=(e)=>{e.preventDefault();changeIncPage('prev');};btns[2].onclick=(e)=>{e.preventDefault();changeIncPage('next');};btns[3].onclick=(e)=>{e.preventDefault();changeIncPage('last');};}const totalPages=Math.ceil((window.globalIncidents?.length||0)/incPageSize)||1;sec.querySelectorAll('span, div').forEach(el=>{if(el.children.length===0&&el.innerText&&el.innerText.includes('/')&&el.innerText.length<10){el.innerText=`${incCurrentPage} / ${totalPages}`;}});}

// دالة التنقل بين صفحات جدول الوقائع (الأولى، السابقة، التالية، الأخيرة) بدون تحريك الشاشة
function changeIncPage(dir){const list=window.globalIncidents||[];const totalPages=Math.ceil(list.length/incPageSize)||1;if(dir==='first')incCurrentPage=1;else if(dir==='prev'&&incCurrentPage>1)incCurrentPage--;else if(dir==='next'&&incCurrentPage<totalPages)incCurrentPage++;else if(dir==='last')incCurrentPage=totalPages;renderSavedIncidents();}

// دالة جلب بيانات الواقعة وتعبئتها في النموذج لتبدأ التعديل فوراً
function editIncident(incId){const list=window.globalIncidents||[];const inc=list.find(x=>(x.ID||x.id)===incId);if(!inc)return alert("الواقعة غير موجودة!");currentIncidentEditId=inc.ID||inc.id;const s=(id,val)=>{const el=document.getElementById(id);if(el)el.value=val||'';};s('incId',inc.ID||inc.id);s('incDate',(inc.Date||inc.date||'').toString().split('T')[0]);s('incTime',inc.Time||inc.time);s('incLocation',inc.Location||inc.location);s('incPersonnel',inc.Personnel_Involved||inc.personnel);s('incPosition',inc.Position||inc.position);s('incInjuryType',inc.Injury_Type||inc.injuryType);s('incAcType',inc.TYPE||inc.type);s('incFlightNo',inc.Flight_No||inc.flightNo);s('incReg',inc.REG||inc.reg);s('incCar',inc.CAR||inc.car);s('incEquipmentNo',inc.Equipment_No||inc.equipmentNo);s('incDriver',inc.Driver_Name||inc.driver);s('incEqOwner',inc.Equipment_Owned||inc.eqOwner);s('incStatus',inc.Status||inc.status);s('incPreparedBy',inc.Prepared_By||inc.preparedBy);s('incChar',inc.Characterization||inc.charaterization);s('incCauses',inc.Occurrence_Causes||inc.causes);s('incRiskSev',inc.Risk_Severity||inc.riskSeverity);s('incRiskProb',inc.Risk_Probability||inc.riskProb);s('incAttach',inc.Attachment_URL||inc.attachment_URL);s('incDesc',inc.Description||inc.description);s('incHazardDesc',inc.Hazard_Description||inc.hazardDesc);s('incCausesDetails',inc.Causes_Details||inc.causesDetails);s('incAction',inc.Action_Taken||inc.actionTaken);s('incRecommendation',inc.Recommendation||inc.recommendation);const btn=document.getElementById('submitIncBtn');if(btn){btn.innerHTML='<i class="fa-solid fa-pen-to-square"></i> تحديث الواقعة';btn.style.backgroundColor='#17a2b8';}switchIncidentTab('entry');}

// دالة حذف واقعة من شيت جوجل والقائمة المحلية وتحديث الجدول
async function deleteIncident(incId){if(!confirm("⚠️ هل أنت متأكد من حذف هذه الواقعة نهائياً من قاعدة البيانات؟"))return;try{await fetch(API_URL,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:"deleteIncident",id:incId})});if(window.globalIncidents){window.globalIncidents=window.globalIncidents.filter(x=>(x.ID||x.id)!==incId);try{localStorage.setItem('rmf_incidents',JSON.stringify(window.globalIncidents));}catch(e){}}alert("✅ تم حذف الواقعة بنجاح!");renderSavedIncidents();}catch(e){alert("❌ فشل الاتصال بالسيرفر لحذف الواقعة.");}}

// دالة مساعدة لتحويل الملف المختار إلى صيغة Base64 تمهيداً لرفعه إلى جوجل درايف
function getBase64(f){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=e=>rej(e);r.readAsDataURL(f);});}

